from pysat.solvers import Solver
from pysat.card import CardEnc, EncType
import time

W = 5
G = 7
S = 5
N = G * S

# Variables: x[w][p][g] = 1 if player p is in group g in week w
def var(w, p, g):
    return w * N * G + p * G + g + 1

solver = Solver(name='m22')

# Each player is in exactly one group per week
for w in range(W):
    for p in range(N):
        vars = [var(w, p, g) for g in range(G)]
        solver.add_clause(vars)
        for i in range(G):
            for j in range(i + 1, G):
                solver.add_clause([-vars[i], -vars[j]])

# Each group has exactly S players
for w in range(W):
    for g in range(G):
        vars = [var(w, p, g) for p in range(N)]
        cnf = CardEnc.equals(lits=vars, bound=S, encoding=EncType.seqcounter, top_id=solver.nv)
        for clause in cnf.clauses:
            solver.add_clause(clause)

# No two players in the same group more than once
# For each pair of players, they can share a group at most once across all weeks.
# Let y[p1][p2][w] = 1 if p1 and p2 are in the same group in week w
# y[p1][p2][w] <-> OR_g (x[w][p1][g] AND x[w][p2][g])
# Actually, we can just say: for any two weeks w1, w2, and any group g1, g2,
# p1 and p2 cannot both be in g1 in w1 AND g2 in w2.
# This means: NOT (x[w1][p1][g1] AND x[w1][p2][g1] AND x[w2][p1][g2] AND x[w2][p2][g2])
# This is O(N^2 * W^2 * G^2) clauses.
# N=35, W=5, G=7. N^2 = 1225. W^2 = 25. G^2 = 49.
# 1225 * 25 * 49 = 1,500,625 clauses. This is manageable.

for p1 in range(N):
    for p2 in range(p1 + 1, N):
        for w1 in range(W):
            for w2 in range(w1 + 1, W):
                for g1 in range(G):
                    for g2 in range(G):
                        solver.add_clause([
                            -var(w1, p1, g1),
                            -var(w1, p2, g1),
                            -var(w2, p1, g2),
                            -var(w2, p2, g2)
                        ])

# Symmetry breaking
# Week 0: players 0..4 in group 0, 5..9 in group 1, etc.
for p in range(N):
    solver.add_clause([var(0, p, p // S)])

# Player 0 is always in group 0
for w in range(W):
    solver.add_clause([var(w, 0, 0)])

# In week 1, the first player of each group from week 0 (0, 5, 10, 15, 20, 25, 30)
# can be assigned to groups 0..6 respectively.
for i in range(G):
    solver.add_clause([var(1, i * S, i)])

print("Solving...")
t0 = time.time()
res = solver.solve()
print("Time:", time.time() - t0)
if res:
    print("SAT")
    model = solver.get_model()
    ans = []
    for w in range(W):
        for p in range(N):
            for g in range(G):
                if model[var(w, p, g) - 1] > 0:
                    ans.append(g)
    print(ans)
else:
    print("UNSAT")

from pysat.solvers import Solver
from pysat.card import CardEnc, EncType
import time

W = 5
G = 7
S = 5
N = G * S

def var(w, p, g):
    return w * N * G + p * G + g + 1

top_id = W * N * G

solver = Solver(name='cadical153')

for w in range(W):
    for p in range(N):
        vars = [var(w, p, g) for g in range(G)]
        solver.add_clause(vars)
        for i in range(G):
            for j in range(i + 1, G):
                solver.add_clause([-vars[i], -vars[j]])

for w in range(W):
    for g in range(G):
        vars = [var(w, p, g) for p in range(N)]
        cnf = CardEnc.equals(lits=vars, bound=S, encoding=EncType.seqcounter, top_id=top_id)
        top_id = max(top_id, cnf.nv)
        for clause in cnf.clauses:
            solver.add_clause(clause)

for p1 in range(N):
    for p2 in range(p1 + 1, N):
        for w1 in range(W):
            for w2 in range(w1 + 1, W):
                for g1 in range(G):
                    for g2 in range(G):
                        solver.add_clause([
                            -var(w1, p1, g1),
                            -var(w1, p2, g1),
                            -var(w2, p1, g2),
                            -var(w2, p2, g2)
                        ])

# Symmetry breaking
for p in range(N):
    solver.add_clause([var(0, p, p // S)])

for w in range(W):
    solver.add_clause([var(w, 0, 0)])

for i in range(G):
    solver.add_clause([var(1, i * S, i)])

print("Solving...")
t0 = time.time()
